package Koha::Plugin::Com::JunaidZaidiLibrary::DigitalCirculation::Controller::Base;
use Mojo::Base 'Mojolicious::Controller'; use Mojo::JSON qw(true false); use Time::HiRes qw(time);
sub safe_error { my($c,$e)=@_; my($status,$code,$message)=(500,'INTERNAL_ERROR','The request could not be completed.'); if($e=~/INVALID_FILTER/){($status,$code,$message)=(400,'INVALID_FILTER','A filter or sort value is invalid.')}elsif($e=~/INVALID_PAGINATION/){($status,$code,$message)=(400,'INVALID_PAGINATION','Pagination is invalid.')} return$c->render(status=>$status,json=>{error=>{code=>$code,message=>$message}}) }
sub query { my($c,$repo,$id_name,$not_found)=@_; my$id=$c->param($id_name); if(defined$id){my$row=eval{$repo->get($id)};return safe_error($c,$@)if$@;return$c->render(status=>404,json=>{error=>{code=>$not_found,message=>'The record was not found.'}})unless$row;return$c->render(json=>$row)} my%q=map{$_=>scalar$c->param($_)}grep{defined$c->param($_)}qw(status patron_id biblio_id portal_request_id requested_from requested_to due_from due_to loan_id event_type aggregate_type aggregate_id request_id delivery_status occurred_from occurred_to page per_page sort direction);my($rows,$total,$page,$pp)=eval{$repo->list(\%q)};return safe_error($c,$@)if$@;return$c->render(json=>{data=>$rows,pagination=>{page=>$page,per_page=>$pp,total=>$total,total_pages=>int(($total+$pp-1)/$pp)}})}
1;
